"""V31 render command adapter; no media generated by this module.
Reuses V28 FFmpeg segment pipeline, adds creator-jacket grading to each source.
Storyboard controls stay in V29/V30. Timing requires final cue QA.
"""
from v28_full_renderer import trim_command
from v31_style_engine import filter_chain

def graded_trim_command(ffmpeg,source,out,source_start,seconds):
    command=trim_command(ffmpeg,source,out,source_start,seconds)
    idx=command.index("-vf")+1
    base=command[idx]
    # Grading after geometry, before output encode. Avoid text overlays.
    command[idx]=base+","+filter_chain()
    return command

def validate_command(cmd):
    if "-an" not in cmd:raise ValueError("shot segment should be silent")
    if "-vf" not in cmd:raise ValueError("video filter missing")
    chain=cmd[cmd.index("-vf")+1]
    if chain.count("scale=1280:720")!=1:raise ValueError("invalid geometry")
    if "eq=contrast=" not in chain or "colorbalance=" not in chain or "noise=alls=" not in chain:
        raise ValueError("jacket style was not applied")
    return True

if __name__=="__main__":
    example=graded_trim_command("ffmpeg","source.mp4","preview.mp4",1.0,5.0)
    assert validate_command(example)
    print("V31 graded FFmpeg command validated; no video rendered")
